class Parser(object):
    '''Encapsulate a format string that may be used to parse other strings.
    '''
    @staticmethod
    def _validate_braces(format_str):
        """Validate that all braces in the format string are properly paired."""
        depth = 0
        i = 0
        while i < len(format_str):
            if format_str[i] == '{':
                if i + 1 < len(format_str) and format_str[i + 1] == '{':
                    # Escaped brace '{{'
                    i += 2
                    continue
                depth += 1
            elif format_str[i] == '}':
                if i + 1 < len(format_str) and format_str[i + 1] == '}':
                    # Escaped brace '}}'
                    i += 2
                    continue
                depth -= 1
                if depth < 0:
                    raise ValueError("Unmatched closing brace '}' in format string")
            i += 1
        if depth != 0:
            raise ValueError("Unmatched opening brace '{' in format string")

    def __init__(self, format, extra_types=None, case_sensitive=False):

